package com.aistock.prediction.modelcatalog;
import com.aistock.prediction.question.*;import com.aistock.prediction.analysis.*;import com.aistock.prediction.explanation.*;import com.fasterxml.jackson.databind.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.context.annotation.*;import org.springframework.test.context.junit.jupiter.SpringJUnitConfig;import org.springframework.test.context.web.WebAppConfiguration;import org.springframework.mock.web.MockCookie;import org.springframework.web.context.WebApplicationContext;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import static org.springframework.security.test.web.servlet.setup.SecurityMockMvcConfigurers.springSecurity;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.junit.jupiter.api.Assertions.*;import static com.aistock.prediction.question.QuestionSamples.*;
@Tag("mysql") @WebAppConfiguration @SpringJUnitConfig(QuestionHttpTest.Config.class)
class QuestionHttpTest {
 static class Client implements MaasClient {int calls;boolean enabled=true;public boolean enabled(){return enabled;}public String model(){return "test";}public JsonNode generate(Map<String,String> f){throw new IllegalStateException();}public JsonNode generateQuestion(String q,Map<String,String> f){calls++;return raw("RISK","{{BASIS_LIMIT}}。","BASIS_LIMIT");}}
 @Configuration @Import({ModelHttpTest.Config.class,QuestionController.class}) static class Config {
 @Bean Client questionClient(){return new Client();}
 @Bean QuestionService questionService(ModelDatabaseFixture db,ObjectMapper m,Client c){return new QuestionService(new QuestionRepository(db.jdbc,m),new AnalysisRepository(db.jdbc,m),c,m,Clock.fixed(QuestionMysqlTest.NOW,ZoneOffset.UTC));}}
 @Autowired WebApplicationContext context;@Autowired Client client;@Autowired ObjectMapper mapper;@Autowired ModelDatabaseFixture db;
 @Test void strictBodyIdentityReplayAndReadOnlyRecovery()throws Exception{new ModelDatabaseFixture();client.calls=0;client.enabled=true;var mvc=MockMvcBuilders.webAppContextSetup(context).apply(springSecurity()).build();var user=new MockCookie("AISTOCK_SESSION","user-session");var csrf=new MockCookie("XSRF-TOKEN","known-csrf");UUID owner=UUID.nameUUIDFromBytes("user-session".getBytes());UUID source=QuestionMysqlTest.seed(db,owner);var in=new QuestionInput(UUID.randomUUID(),source,"有哪些风险？");String body=mapper.writeValueAsString(in),uri="/api/v1/stock-questions";
 mvc.perform(get(uri).param("analysisId",source.toString())).andExpect(status().isUnauthorized());mvc.perform(post(uri).cookie(user).contentType("application/json").content(body)).andExpect(status().isForbidden());
 for(String bad:List.of(body+"{}",body.replace("\"question\":","\"question\":\"重复\",\"question\":"),body.substring(0,body.length()-1)+",\"facts\":{}}")){mvc.perform(post(uri).cookie(user,csrf).header("Origin","http://127.0.0.1:15173").header("X-XSRF-TOKEN","known-csrf").contentType("application/json").content(bad)).andExpect(status().isBadRequest());}assertEquals(0,client.calls);
 var response=mvc.perform(post(uri).cookie(user,csrf).header("Origin","http://127.0.0.1:15173").header("X-XSRF-TOKEN","known-csrf").contentType("application/json").content(body)).andExpect(status().isOk()).andExpect(jsonPath("$.data.state").value("SUCCEEDED")).andReturn();String answer=mapper.readTree(response.getResponse().getContentAsString()).path("data").path("answerId").asText();client.enabled=false;
 mvc.perform(post(uri).cookie(user,csrf).header("Origin","http://127.0.0.1:15173").header("X-XSRF-TOKEN","known-csrf").contentType("application/json").content(body)).andExpect(status().isOk());mvc.perform(get(uri+"/operations/"+in.operationId()).cookie(user)).andExpect(status().isOk());mvc.perform(get(uri).cookie(user).param("analysisId",source.toString())).andExpect(status().isOk()).andExpect(jsonPath("$.data.total").value(1));mvc.perform(get(uri+"/"+answer).cookie(new MockCookie("AISTOCK_SESSION","admin-session"))).andExpect(status().isNotFound());assertEquals(1,client.calls);}
}
